/* ---------------------------------------------------------------------------
 * Design tokens — generated from the Figma library "Shadcn Components"
 * https://www.figma.com/community/file/1342715840824755935
 *
 * Figma variable collections mapped here:
 *   mode              -> semantic shadcn tokens (colors + radius scale), 2 modes
 *   tw/font           -> font family / size / weight / leading / tracking
 *   tw/gap            -> spacing scale (gap-*, gap-x-*, gap-y-*)
 *   tw/border-radius  -> raw Tailwind radii (rounded-*)
 *   tw/border-width   -> border-*, border-{t,r,b,l,s,e}-*
 *   tw/max-height, tw/min-height, ... -> raw Tailwind sizing
 *   rdx/colors        -> Radix colour scales (chart palette lives here)
 *
 * Every value below with a "figma:" comment was read back from the file.
 * Values marked "derived:" are not directly observable through the REST API
 * with the current token scope (the whole file is pinned to the light mode).
 * ------------------------------------------------------------------------- */

@import "tailwindcss";
@import "tw-animate-css";

/* Consumers importing this file from node_modules need the library's own
   sources registered so Tailwind emits the utilities the components use. */
@source "../components";
@source "../lib";

@custom-variant dark (&:is(.dark *));

/* -------------------------------------------------------------------------
 * 1. Semantic tokens — Figma collection `mode`
 * ---------------------------------------------------------------------- */

:root {
  /* Radius scale. Figma stores absolute px; shadcn derives them from --radius.
     radius-lg == --radius is the anchor (figma: radius-lg = 10). */
  --radius: 0.625rem;                        /* 10px  */
  --radius-none: 0rem;                       /* figma: radius-none  = 0     */
  --radius-xs: calc(var(--radius) - 6px);    /* 4px   (derived)             */
  --radius-sm: calc(var(--radius) - 4px);    /* figma: radius-sm    = 6     */
  --radius-md: calc(var(--radius) - 2px);    /* figma: radius-md    = 8     */
  --radius-lg: var(--radius);                /* figma: radius-lg    = 10    */
  --radius-xl: calc(var(--radius) + 4px);    /* figma: radius-xl    = 14    */
  --radius-2xl: calc(var(--radius) + 8px);   /* figma: radius-2xl   = 18    */
  --radius-3xl: calc(var(--radius) + 12px);  /* figma: radius-3xl   = 22    */
  --radius-4xl: calc(var(--radius) + 16px);  /* figma: radius-4xl   = 26    */
  --radius-full: 9999px;                     /* figma: radius-full  = 9999  */

  /* Surfaces */
  --background: #ffffff;                     /* figma: background            */
  --foreground: #0a0a0a;                     /* figma: foreground   neutral-950 */
  --card: #ffffff;                           /* figma: card                  */
  --card-foreground: #0a0a0a;                /* figma: card-foreground       */
  --popover: #ffffff;                        /* figma: popover               */
  --popover-foreground: #0a0a0a;             /* figma: popover-foreground    */

  /* Actions */
  --primary: #171717;                        /* figma: primary      neutral-900 */
  --primary-foreground: #fafafa;             /* figma: primary-foreground  neutral-50 */
  --secondary: #f5f5f5;                      /* figma: secondary    neutral-100 */
  --secondary-foreground: #0a0a0a;           /* figma: secondary-foreground  */
  --muted: #f5f5f5;                          /* figma: muted        neutral-100 */
  --muted-foreground: #737373;               /* figma: muted-foreground neutral-500 */
  --accent: #f5f5f5;                         /* figma: accent       neutral-100 */
  --accent-foreground: #171717;              /* derived (mirrors sidebar-accent-foreground) */

  /* Destructive. The Figma file splits this into three tokens rather than the
     stock shadcn `destructive` / `destructive-foreground` pair. */
  --destructive: #e7000b;                    /* figma: destructive   red-600  */
  --destructive-foreground: #fafafa;         /* derived                       */
  --text-destructive: #e7000b;               /* figma: text-destructive       */
  --destructive-subtle: #e7000b1a;           /* figma: destructive-subtle 10% */

  /* Lines & focus */
  --border: #e5e5e5;                         /* figma: sidebar-border neutral-200 */
  --input: #e5e5e5;                          /* figma: input        neutral-200 */
  --ring: #737373;                           /* figma: ring         neutral-500 */

  /* Charts — Radix `blue` steps 8..12 (figma collection rdx/colors) */
  --chart-1: #5eb1ef;                        /* figma: chart-1  blue/8  */
  --chart-2: #0090ff;                        /* figma: chart-2  blue/9  */
  --chart-3: #0588f0;                        /* figma: chart-3  blue/10 */
  --chart-4: #0d74ce;                        /* figma: chart-4  blue/11 */
  --chart-5: #113264;                        /* figma: chart-5  blue/12 */

  /* Sidebar */
  --sidebar: #fafafa;                        /* figma: sidebar      neutral-50  */
  --sidebar-foreground: #0a0a0a;             /* figma: sidebar-foreground       */
  --sidebar-primary: #171717;                /* figma: sidebar-primary          */
  --sidebar-primary-foreground: #fafafa;     /* figma: sidebar-primary-foreground */
  --sidebar-accent: #f5f5f5;                 /* figma: sidebar-accent           */
  --sidebar-accent-foreground: #171717;      /* figma: sidebar-accent-foreground */
  --sidebar-border: #e5e5e5;                 /* figma: sidebar-border           */
  --sidebar-ring: #737373;                   /* derived (= ring)                */

  /* Effect styles — Figma "Box Shadow/*" */
  --shadow-2xs: 0 1px 0 0 rgb(0 0 0 / 0.05);
  --shadow-xs: 0 1px 2px 0 rgb(0 0 0 / 0.10);                                  /* figma: Box Shadow/shadow-xs */
  --shadow-sm: 0 1px 2px -1px rgb(0 0 0 / 0.10), 0 1px 3px 0 rgb(0 0 0 / 0.10);
  --shadow-md: 0 2px 4px -2px rgb(0 0 0 / 0.10), 0 4px 6px -1px rgb(0 0 0 / 0.10);  /* figma: Box Shadow/shadow-md */
  --shadow-lg: 0 4px 6px -4px rgb(0 0 0 / 0.10), 0 10px 15px -3px rgb(0 0 0 / 0.10);/* figma: Box Shadow/shadow-lg */
  --shadow-xl: 0 8px 10px -6px rgb(0 0 0 / 0.10), 0 20px 25px -5px rgb(0 0 0 / 0.10);
  --shadow-2xl: 0 25px 50px -12px rgb(0 0 0 / 0.25);

  /* Focus treatment. The file draws focus as a 3px spread drop-shadow rather
     than an outline, which is why every focusable component below uses
     ring-[3px] instead of the older shadcn ring-2 + offset. */
  --focus-ring: 0 0 0 3px #a1a1a180;         /* figma: Box Shadow/Focus ring  neutral-400 @ 50% */
  --focus-ring-destructive: 0 0 0 3px #dc262633; /* figma: Box Shadow/Destructive  red @ 20% */
  --ring-alpha: #a1a1a180;
  --ring-destructive-alpha: #dc262633;
}

.dark {
  /* derived: the Figma `mode` collection ships a dark mode, but every frame in
     the file is pinned to light so the values are not readable through the
     REST API on a file_content:read token. These mirror the light mapping onto
     the Tailwind neutral ramp and match shadcn's own dark defaults. Re-sync
     with the real values by pasting globals.css from ui.shadcn.com/create into
     the "shadcn/ui create" Figma plugin. */
  --background: #0a0a0a;
  --foreground: #fafafa;
  --card: #171717;
  --card-foreground: #fafafa;
  --popover: #262626;
  --popover-foreground: #fafafa;

  --primary: #e5e5e5;
  --primary-foreground: #171717;
  --secondary: #262626;
  --secondary-foreground: #fafafa;
  --muted: #262626;
  --muted-foreground: #a1a1a1;
  --accent: #404040;
  --accent-foreground: #fafafa;

  --destructive: #ff6467;
  --destructive-foreground: #fafafa;
  --text-destructive: #ff6467;
  --destructive-subtle: #ff64671f;

  --border: #ffffff1a;
  --input: #ffffff26;
  --ring: #737373;

  /* Radix `blueDark` steps 8..12 */
  --chart-1: #2870bd;
  --chart-2: #0090ff;
  --chart-3: #3b9eff;
  --chart-4: #70b8ff;
  --chart-5: #c2e6ff;

  --sidebar: #171717;
  --sidebar-foreground: #fafafa;
  --sidebar-primary: #e5e5e5;
  --sidebar-primary-foreground: #171717;
  --sidebar-accent: #262626;
  --sidebar-accent-foreground: #fafafa;
  --sidebar-border: #ffffff1a;
  --sidebar-ring: #737373;

  --focus-ring: 0 0 0 3px #a1a1a180;
  --focus-ring-destructive: 0 0 0 3px #ff646733;
  --ring-alpha: #a1a1a180;
  --ring-destructive-alpha: #ff646733;
}

/* -------------------------------------------------------------------------
 * 2. Tailwind theme wiring
 * ---------------------------------------------------------------------- */

@theme inline {
  /* Typography — Figma collection tw/font. The file uses Inter for
     `family/sans` and never overrides tracking (tracking/normal = 0). */
  --font-sans: Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI",
    Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas,
    "Liberation Mono", monospace;

  /* size/* + leading/* pairs exactly as they are paired in the Figma
     text styles (Text-xs … Text-4xl x 9 weights). */
  --text-xs: 0.75rem;      --text-xs--line-height: 1rem;      /* 12 / 16 */
  --text-sm: 0.875rem;     --text-sm--line-height: 1.25rem;   /* 14 / 20 */
  --text-base: 1rem;       --text-base--line-height: 1.5rem;  /* 16 / 24 */
  --text-lg: 1.125rem;     --text-lg--line-height: 1.75rem;   /* 18 / 28 */
  --text-xl: 1.25rem;      --text-xl--line-height: 1.75rem;   /* 20 / 28 */
  --text-2xl: 1.5rem;      --text-2xl--line-height: 2rem;     /* 24 / 32 */
  --text-3xl: 1.875rem;    --text-3xl--line-height: 2.25rem;  /* 30 / 36 */
  --text-4xl: 2.25rem;     --text-4xl--line-height: 2.5rem;   /* 36 / 40 */

  --font-weight-thin: 100;
  --font-weight-extralight: 200;
  --font-weight-light: 300;
  --font-weight-normal: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;
  --font-weight-extrabold: 800;
  --font-weight-black: 900;

  /* Colors */
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-text-destructive: var(--text-destructive);
  --color-destructive-subtle: var(--destructive-subtle);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  /* The file paints focus as a 3px drop-shadow in neutral-400 @ 50% rather
     than in `ring`, so it gets its own token. */
  --color-ring-subtle: var(--ring-alpha);
  --color-ring-destructive: var(--ring-destructive-alpha);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);

  /* Radii — exposes the `mode` radius ramp as rounded-* utilities */
  --radius-none: var(--radius-none);
  --radius-xs: var(--radius-xs);
  --radius-sm: var(--radius-sm);
  --radius-md: var(--radius-md);
  --radius-lg: var(--radius-lg);
  --radius-xl: var(--radius-xl);
  --radius-2xl: var(--radius-2xl);
  --radius-3xl: var(--radius-3xl);
  --radius-4xl: var(--radius-4xl);

  /* Motion. The Figma file has no motion spec, so these are the shadcn
     defaults; they are listed here so they stay tokenised rather than inline. */
  --animate-accordion-down: accordion-down 0.2s ease-out;
  --animate-accordion-up: accordion-up 0.2s ease-out;
  --animate-caret-blink: caret-blink 1.25s ease-out infinite;

  /* Shadows */
  --shadow-2xs: var(--shadow-2xs);
  --shadow-xs: var(--shadow-xs);
  --shadow-sm: var(--shadow-sm);
  --shadow-md: var(--shadow-md);
  --shadow-lg: var(--shadow-lg);
  --shadow-xl: var(--shadow-xl);
  --shadow-2xl: var(--shadow-2xl);
}

/* -------------------------------------------------------------------------
 * 3. Base layer
 * ---------------------------------------------------------------------- */

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground font-sans;
    font-feature-settings: "cv11", "ss01";
    font-variation-settings: "opsz" 32;
    -webkit-font-smoothing: antialiased;
  }
  /* Icons: the Figma file uses a 2px stroke on every Lucide glyph
     (tw/stroke -> stroke-width = 2, stroke-2 = 2) except inside Command,
     Calendar and Sidebar where stroke-1 is used. */
  svg:not([class*="stroke-"]) {
    stroke-width: 2;
  }
  svg:not([class*="size-"]):not([class*="w-"]):not([class*="h-"]) {
    width: 1rem;
    height: 1rem;
  }
}

@keyframes accordion-down {
  from { height: 0; }
  to { height: var(--radix-accordion-content-height); }
}
@keyframes accordion-up {
  from { height: var(--radix-accordion-content-height); }
  to { height: 0; }
}
@keyframes caret-blink {
  0%, 70%, 100% { opacity: 1; }
  20%, 50% { opacity: 0; }
}
